import type { Localized, Lesson, Flashcard, Question, Activity, Lab, ExternalResource } from '../types';
import type { WeekContent } from '../weekContent';
const L=(en:string,es:string,pt:string):Localized=>({en,es,pt});
type CheckData=[Localized,Localized,Localized,Localized,Localized,string,Localized,Localized,Localized];
const mkLesson=(id:string,title:Localized,body:Localized[],analogy:Localized,takeaways:Localized[],cq:CheckData,exercises:{title:Localized;prompt:Localized;hint:Localized;solution:Localized;level:1|2|3}[],code?:{language:string;caption:Localized;source:string}):Lesson=>({id,title,minutes:25,body,analogy,takeaways,check:{question:cq[0],options:[cq[1],cq[2],cq[3],cq[4]],answer:Number(cq[5]),explanation:cq[6]},pitfalls:[{mistake:cq[7],fix:cq[8]}],exercises:exercises.map((e,i)=>({id:`${id}-ex${i+1}`,...e})),...(code?{code}:{})});
const card=(id:string,lessonId:string,front:Localized,back:Localized,kind:'concept'|'distinction'='concept'):Flashcard=>({id,lessonId,front,back,kind});
const mc=(id:string,lessonId:string,prompt:Localized,options:Localized[],answer:number,explanation:Localized):Question=>({id,lessonId,type:'multiple-choice',prompt,options,answer,explanation});
const tf=(id:string,lessonId:string,prompt:Localized,answer:boolean,explanation:Localized):Question=>({id,lessonId,type:'true-false',prompt,options:[L('True','Verdadero','Verdadeiro'),L('False','Falso','Falso')],answer:answer?0:1,explanation});
const fill=(id:string,lessonId:string,prompt:Localized,accepted:string[],explanation:Localized):Question=>({id,lessonId,type:'fill-blank',prompt,accepted,explanation});
const short=(id:string,lessonId:string,prompt:Localized,accepted:string[],explanation:Localized):Question=>({id,lessonId,type:'short-answer',prompt,accepted,explanation});
const ord=(id:string,lessonId:string,title:Localized,prompt:Localized,items:Localized[],explanation:Localized):Activity=>({id,lessonId,kind:'order',title,prompt,items,explanation});
const lab=(id:string,title:Localized,goal:Localized,steps:{title:Localized;expected:Localized}[]):Lab=>({id,kind:'design',level:2,title,goal,minutes:35,steps:steps.map((s,i)=>({id:`${id}-s${i+1}`,title:s.title,commands:[],expected:s.expected}))});
const res=(id:string,title:string,url:string,note:Localized):ExternalResource=>({id,title,url,kind:'article',verifiedOn:'2026-11-04',note});
const X=(n:string,es:string,pt:string)=>L(n,es,pt);
const lessons:Lesson[]=[
 mkLesson('hist2-l1',X('What software engineering is','Qué es la ingeniería de software','O que é engenharia de software'),[
  X('Software engineering applies systematic, disciplined methods to software development, operation, and maintenance. It includes code, but also requirements, design, testing, deployment, documentation, teamwork, and decisions about acceptable risk.','La ingeniería de software aplica métodos sistemáticos y disciplinados al desarrollo, operación y mantenimiento del software. Incluye código, pero también requisitos, diseño, pruebas, despliegue, documentación, trabajo en equipo y decisiones sobre riesgos aceptables.','A engenharia de software aplica métodos sistemáticos e disciplinados ao desenvolvimento, operação e manutenção de software. Inclui código, mas também requisitos, projeto, testes, implantação, documentação, trabalho em equipe e decisões sobre riscos aceitáveis.'),
  X('The term gained visibility at the 1968 NATO conference, where practitioners discussed problems caused by software complexity and unreliable delivery. The meeting did not instantly solve those problems; it helped frame software work as an engineering challenge requiring repeatable practices and evidence.','El término ganó visibilidad en la conferencia de la OTAN de 1968, donde profesionales analizaron problemas de complejidad y entregas poco confiables. La reunión no resolvió esos problemas de inmediato; ayudó a plantear el trabajo de software como un desafío de ingeniería que requiere prácticas repetibles y evidencia.','O termo ganhou visibilidade na conferência da OTAN de 1968, quando profissionais discutiram problemas de complexidade e entregas pouco confiáveis. O encontro não resolveu esses problemas de imediato; ajudou a apresentar o trabalho de software como um desafio de engenharia que exige práticas repetíveis e evidências.')],
 X('Building a bridge is not only placing beams; software engineering similarly includes planning, inspection, operation, and repair around the code.','Construir un puente no consiste solo en colocar vigas; la ingeniería de software también incluye planificación, inspección, operación y reparación alrededor del código.','Construir uma ponte não é apenas colocar vigas; a engenharia de software também inclui planejamento, inspeção, operação e reparo além do código.'),
 [X('Engineering practice connects technical work with quality, context, and responsibility.','La práctica de ingeniería conecta el trabajo técnico con la calidad, el contexto y la responsabilidad.','A prática de engenharia conecta o trabalho técnico à qualidade, ao contexto e à responsabilidade.'),X('A process should fit the product’s risks and constraints.','El proceso debe adaptarse a los riesgos y restricciones del producto.','O processo deve se adequar aos riscos e restrições do produto.')],
 [X('Which best describes software engineering?','¿Qué describe mejor la ingeniería de software?','O que melhor descreve a engenharia de software?'),X('Disciplined work across software development and maintenance.','Trabajo disciplinado durante el desarrollo y mantenimiento del software.','Trabalho disciplinado no desenvolvimento e na manutenção de software.'),X('Writing code as quickly as possible.','Escribir código lo más rápido posible.','Escrever código o mais rápido possível.'),X('Buying hardware for a project.','Comprar hardware para un proyecto.','Comprar hardware para um projeto.'),X('A guarantee that no defects will occur.','Una garantía de que no habrá defectos.','Uma garantia de que não haverá defeitos.'),'0',X('The discipline spans the software life cycle and uses engineering judgment.','La disciplina abarca el ciclo de vida del software y aplica criterio de ingeniería.','A disciplina abrange o ciclo de vida do software e aplica julgamento de engenharia.'),X('Equating engineering with coding alone.','Equiparar ingeniería únicamente con programación.','Equiparar engenharia apenas a programação.'),X('Include requirements, validation, operation, and maintenance in the definition.','Incluye requisitos, validación, operación y mantenimiento en la definición.','Inclua requisitos, validação, operação e manutenção na definição.')],
 [
  {title:X('Define the boundary','Define el alcance','Defina o escopo'),prompt:X('A team writes code, but never checks whether it meets user needs. What engineering work is missing?','Un equipo escribe código, pero no verifica si satisface las necesidades de usuarios. ¿Qué trabajo de ingeniería falta?','Uma equipe escreve código, mas não verifica se atende às necessidades dos usuários. Que trabalho de engenharia falta?'),hint:X('Think before and after implementation.','Piensa en lo que ocurre antes y después de implementar.','Pense no que acontece antes e depois da implementação.'),solution:X('It needs requirements or stakeholder validation, plus testing and ongoing maintenance planning.','Necesita requisitos o validación con partes interesadas, además de pruebas y planificación de mantenimiento.','Precisa de requisitos ou validação com as partes interessadas, além de testes e planejamento de manutenção.'),level:1},
  {title:X('Explain the 1968 context','Explica el contexto de 1968','Explique o contexto de 1968'),prompt:X('Why did software complexity motivate an engineering approach?','¿Por qué la complejidad del software motivó un enfoque de ingeniería?','Por que a complexidade do software motivou uma abordagem de engenharia?'),hint:X('Consider scale, reliability, and coordination.','Considera escala, confiabilidad y coordinación.','Considere escala, confiabilidade e coordenação.'),solution:X('Larger, harder-to-predict systems exposed weaknesses in ad hoc coding; teams needed repeatable ways to coordinate, validate, and maintain work.','Los sistemas más grandes e impredecibles mostraron límites de la programación improvisada; los equipos necesitaban formas repetibles de coordinar, validar y mantener el trabajo.','Sistemas maiores e menos previsíveis expuseram limites da programação improvisada; equipes precisavam de formas repetíveis de coordenar, validar e manter o trabalho.'),level:2}
 ],{language:'text',caption:X('A compact software life cycle','Ciclo de vida breve del software','Ciclo de vida breve do software'),source:'Needs → Specification → Design & build → Validation → Operation → Evolution'}) ,
 mkLesson('hist2-l2',X('Life-cycle activities','Actividades del ciclo de vida','Atividades do ciclo de vida'),[
  X('A software life cycle organizes work from an idea through delivery and continued change. Common activities include understanding needs, specifying expected behavior, designing a solution, implementing it, validating results, releasing it, and evolving it. These activities can overlap or repeat.','El ciclo de vida organiza el trabajo desde una idea hasta la entrega y los cambios posteriores. Entre las actividades comunes están comprender necesidades, especificar el comportamiento esperado, diseñar una solución, implementarla, validar resultados, publicarla y evolucionarla. Estas actividades pueden solaparse o repetirse.','O ciclo de vida organiza o trabalho desde uma ideia até a entrega e as mudanças posteriores. Atividades comuns incluem compreender necessidades, especificar o comportamento esperado, projetar uma solução, implementá-la, validar resultados, lançá-la e evoluí-la. Essas atividades podem se sobrepor ou se repetir.'),
  X('Validation asks whether the product behaves as intended; verification asks whether a work product meets its stated specification. Testing is one way to gather evidence, but reviews, analysis, and operational feedback also matter. A process model gives a team a useful map, not a substitute for judgment.','La validación pregunta si el producto se comporta como se necesita; la verificación pregunta si un producto de trabajo cumple su especificación. Las pruebas aportan evidencia, pero también importan las revisiones, el análisis y los comentarios de operación. Un modelo de proceso ofrece un mapa útil, no sustituye el criterio.','Validação pergunta se o produto se comporta como necessário; verificação pergunta se um produto de trabalho atende à especificação. Testes fornecem evidências, mas revisões, análises e retorno da operação também importam. Um modelo de processo oferece um mapa útil, não substitui o julgamento.')],
 X('A recipe gives a sequence, but a cook still checks taste and adjusts when ingredients differ.','Una receta propone pasos, pero quien cocina prueba y ajusta si los ingredientes cambian.','Uma receita propõe etapas, mas quem cozinha prova e ajusta quando os ingredientes mudam.'),
 [X('Requirements, construction, validation, and evolution are connected activities.','Requisitos, construcción, validación y evolución son actividades conectadas.','Requisitos, construção, validação e evolução são atividades conectadas.'),X('Feedback may send a team back to revise an earlier decision.','La retroalimentación puede llevar al equipo a revisar una decisión anterior.','O retorno pode levar a equipe a rever uma decisão anterior.')],
 [X('What is the purpose of validation?','¿Cuál es el propósito de la validación?','Qual é o objetivo da validação?'),X('Assess whether the product meets intended needs.','Evaluar si el producto satisface las necesidades previstas.','Avaliar se o produto atende às necessidades pretendidas.'),X('Prove that all future changes are impossible.','Probar que ningún cambio futuro será posible.','Provar que nenhuma mudança futura será possível.'),X('Replace requirements work.','Reemplazar el trabajo de requisitos.','Substituir o trabalho de requisitos.'),X('Guarantee a project stays within budget.','Garantizar que el proyecto no supere el presupuesto.','Garantir que o projeto fique dentro do orçamento.'),'0',X('Validation compares the result with intended use and stakeholder needs.','La validación compara el resultado con el uso previsto y las necesidades de las partes interesadas.','A validação compara o resultado com o uso pretendido e as necessidades das partes interessadas.'),X('Treating testing as the entire validation process.','Tratar las pruebas como todo el proceso de validación.','Tratar os testes como todo o processo de validação.'),X('Use tests plus reviews, analysis, and operational feedback when appropriate.','Usa pruebas, revisiones, análisis y comentarios de operación según corresponda.','Use testes, revisões, análises e retorno operacional quando apropriado.')],
 [
  {title:X('Map the activities','Mapea las actividades','Mapeie as atividades'),prompt:X('A client changes an important need after a prototype review. What activities should happen next?','Un cliente cambia una necesidad importante después de revisar un prototipo. ¿Qué actividades siguen?','Um cliente muda uma necessidade importante após revisar um protótipo. Que atividades devem ocorrer em seguida?'),hint:X('The team should not jump straight to coding.','El equipo no debe saltar directamente a programar.','A equipe não deve pular diretamente para a programação.'),solution:X('Clarify and revise the requirement, assess design and impact, implement the change, then validate it with relevant stakeholders.','Aclarar y revisar el requisito, evaluar el diseño y el impacto, implementar el cambio y validarlo con las partes interesadas.','Esclarecer e revisar o requisito, avaliar o projeto e o impacto, implementar a mudança e validá-la com as partes interessadas.'),level:2},
  {title:X('Verification or validation?','¿Verificación o validación?','Verificação ou validação?'),prompt:X('A reviewer checks that a calculation module matches its documented formula. Which question is being asked?','Una persona revisora comprueba que un módulo coincide con la fórmula documentada. ¿Qué pregunta hace?','Uma pessoa revisora verifica se um módulo corresponde à fórmula documentada. Que pergunta está sendo feita?'),hint:X('Compare the artifact with its specification.','Compara el artefacto con su especificación.','Compare o artefato à especificação.'),solution:X('This is verification: checking conformance to a stated specification.','Es verificación: comprobar la conformidad con una especificación.','É verificação: conferir a conformidade com uma especificação.'),level:1}
 ]),
 mkLesson('hist2-l3',X('Process models and team coordination','Modelos de proceso y coordinación de equipos','Modelos de processo e coordenação de equipes'),[
  X('A process model describes how a team organizes activities, decisions, and feedback. Sequential plans can make dependencies and approvals visible; incremental approaches release parts of a system and use what is learned to shape later work. Real teams often combine practices to suit constraints.','Un modelo de proceso describe cómo un equipo organiza actividades, decisiones y retroalimentación. Los planes secuenciales hacen visibles dependencias y aprobaciones; los enfoques incrementales entregan partes del sistema y usan lo aprendido para orientar el trabajo posterior. Los equipos reales suelen combinar prácticas.','Um modelo de processo descreve como uma equipe organiza atividades, decisões e retorno. Planos sequenciais tornam dependências e aprovações visíveis; abordagens incrementais entregam partes do sistema e usam o aprendizado para orientar o trabalho seguinte. Equipes reais costumam combinar práticas.'),
  X('Software work involves people with different perspectives: users explain goals, designers structure solutions, developers build them, testers evaluate behavior, and operators support them in use. Responsibilities may overlap in small teams. Clear communication and ownership reduce handoff gaps, but no single team structure fits every project.','El trabajo de software reúne perspectivas distintas: usuarios explican objetivos, diseñadores estructuran soluciones, desarrolladores construyen, testers evalúan el comportamiento y operadores apoyan el uso. En equipos pequeños, las responsabilidades pueden combinarse. La comunicación y la responsabilidad claras reducen vacíos, pero ningún equipo sirve para todos los proyectos.','O trabalho de software reúne perspectivas diferentes: usuários explicam objetivos, designers estruturam soluções, desenvolvedores constroem, testadores avaliam o comportamento e operadores apoiam o uso. Em equipes pequenas, responsabilidades podem se combinar. Comunicação e responsabilidade claras reduzem lacunas, mas nenhuma estrutura serve a todos os projetos.')],
 X('A film crew has specialized roles, yet the director and editor coordinate the pieces into one story.','Un equipo de filmación tiene roles especializados, pero la dirección y edición coordinan las partes en una sola historia.','Uma equipe de cinema tem funções especializadas, mas direção e edição coordenam as partes em uma única história.'),
 [X('Process models make assumptions and feedback paths visible.','Los modelos de proceso hacen visibles supuestos y rutas de retroalimentación.','Modelos de processo tornam visíveis pressupostos e caminhos de retorno.'),X('Team roles should coordinate around shared outcomes.','Los roles deben coordinarse alrededor de resultados compartidos.','As funções devem se coordenar em torno de resultados compartilhados.')],
 [X('Why might a team use an incremental approach?','¿Por qué un equipo usaría un enfoque incremental?','Por que uma equipe usaria uma abordagem incremental?'),X('To deliver usable parts and learn from feedback between increments.','Para entregar partes utilizables y aprender de la retroalimentación entre incrementos.','Para entregar partes utilizáveis e aprender com o retorno entre incrementos.'),X('To avoid all communication with users.','Para evitar toda comunicación con usuarios.','Para evitar toda comunicação com usuários.'),X('To eliminate testing.','Para eliminar las pruebas.','Para eliminar testes.'),X('To guarantee stable requirements.','Para garantizar requisitos estables.','Para garantir requisitos estáveis.'),'0',X('Incremental delivery creates opportunities to inspect results and adapt future work.','La entrega incremental crea oportunidades para revisar resultados y adaptar el trabajo futuro.','A entrega incremental cria oportunidades para inspecionar resultados e adaptar o trabalho futuro.'),X('Assuming roles must always be separate people.','Suponer que cada rol debe corresponder a una persona distinta.','Supor que cada função deve corresponder a uma pessoa diferente.'),X('Describe responsibilities; then say how a team may combine them.','Describe responsabilidades y luego explica cómo un equipo puede combinarlas.','Descreva responsabilidades e depois explique como uma equipe pode combiná-las.')],
 [
  {title:X('Choose a process fit','Elige un proceso adecuado','Escolha um processo adequado'),prompt:X('A small team is testing a new idea with uncertain users and needs. What feature should its process support?','Un equipo pequeño prueba una idea nueva con usuarios y necesidades inciertas. ¿Qué debe permitir su proceso?','Uma equipe pequena testa uma ideia nova com usuários e necessidades incertas. O que o processo deve permitir?'),hint:X('Think about learning before a large commitment.','Piensa en aprender antes de un compromiso grande.','Pense em aprender antes de um grande compromisso.'),solution:X('Short feedback cycles, prototypes, and revision are useful because assumptions may change.','Son útiles los ciclos breves de retroalimentación, los prototipos y la revisión porque los supuestos pueden cambiar.','Ciclos curtos de retorno, protótipos e revisão são úteis porque os pressupostos podem mudar.'),level:2},
  {title:X('Clarify ownership','Aclara responsabilidades','Esclareça responsabilidades'),prompt:X('A deployment failure is reported, but nobody knows who investigates it. Name a coordination improvement.','Se informa un fallo de despliegue, pero nadie sabe quién lo investiga. Nombra una mejora de coordinación.','Uma falha de implantação é relatada, mas ninguém sabe quem a investiga. Cite uma melhoria de coordenação.'),hint:X('Make the response path explicit.','Haz explícita la ruta de respuesta.','Torne explícito o caminho de resposta.'),solution:X('Assign an owner or on-call responsibility, define escalation and communication steps, and record the result for future prevention.','Asigna una persona responsable, define pasos de escalamiento y comunicación, y registra el resultado para prevenir recurrencias.','Atribua uma pessoa responsável, defina etapas de escalonamento e comunicação e registre o resultado para evitar recorrências.'),level:1}
 ])
];
// Add two case-focused lessons to complete the introduction to professional practice.
lessons.push(
 mkLesson('hist2-l4',X('Quality, maintenance, and change','Calidad, mantenimiento y cambio','Qualidade, manutenção e mudança'),[
  X('Software quality is multidimensional. Correct behavior matters, but so do reliability, security, accessibility, usability, performance, and maintainability. Stakeholders may value these qualities differently, so the team should make important quality goals explicit and choose evidence that can evaluate them.','La calidad del software tiene varias dimensiones. Importa el comportamiento correcto, pero también la confiabilidad, seguridad, accesibilidad, facilidad de uso, rendimiento y mantenibilidad. Las partes interesadas pueden valorar estas cualidades de manera distinta; el equipo debe explicitar los objetivos y elegir evidencia para evaluarlos.','A qualidade do software tem várias dimensões. O comportamento correto importa, assim como confiabilidade, segurança, acessibilidade, usabilidade, desempenho e manutenibilidade. As partes interessadas podem valorizar essas qualidades de formas distintas; a equipe deve explicitar objetivos e escolher evidências para avaliá-los.'),
  X('Software continues to change after release: users find problems, policies shift, devices evolve, and new needs appear. Maintenance can correct faults, adapt software to a changed environment, or improve structure. Planning for change early is often less costly than treating a released product as finished forever.','El software cambia después de publicarse: aparecen problemas, cambian políticas y dispositivos, y surgen nuevas necesidades. El mantenimiento puede corregir fallos, adaptar el producto o mejorar su estructura. Planificar el cambio desde temprano suele costar menos que tratar el producto publicado como algo terminado para siempre.','O software muda após o lançamento: usuários encontram problemas, políticas e dispositivos mudam e novas necessidades surgem. A manutenção pode corrigir falhas, adaptar o produto ou melhorar sua estrutura. Planejar mudanças desde cedo costuma custar menos do que tratar um produto lançado como algo para sempre concluído.')],
 X('A public building is judged not only at opening day; safety checks and repairs continue as people use it.','Un edificio público no se evalúa solo el día de apertura; las inspecciones y reparaciones continúan mientras se usa.','Um edifício público não é avaliado apenas no dia da abertura; inspeções e reparos continuam durante o uso.'),
 [X('Quality goals should be named and evaluated.','Los objetivos de calidad deben nombrarse y evaluarse.','Objetivos de qualidade devem ser nomeados e avaliados.'),X('Operation and maintenance are part of the software life cycle.','La operación y el mantenimiento forman parte del ciclo de vida.','Operação e manutenção fazem parte do ciclo de vida do software.')],
 [X('Which is a maintenance activity?','¿Cuál es una actividad de mantenimiento?','Qual é uma atividade de manutenção?'),X('Adapting a released service to a changed operating environment.','Adaptar un servicio publicado a un entorno operativo que cambió.','Adaptar um serviço lançado a um ambiente operacional que mudou.'),X('Declaring the product complete forever.','Declarar el producto terminado para siempre.','Declarar o produto concluído para sempre.'),X('Removing all user feedback.','Eliminar todos los comentarios de usuarios.','Eliminar todo retorno dos usuários.'),X('Avoiding quality goals.','Evitar objetivos de calidad.','Evitar objetivos de qualidade.'),'0',X('Maintenance keeps software useful as faults and environments change.','El mantenimiento conserva la utilidad del software frente a fallos y cambios del entorno.','A manutenção mantém o software útil diante de falhas e mudanças no ambiente.'),X('Reducing quality to the absence of visible bugs.','Reducir la calidad a no tener errores visibles.','Reduzir qualidade à ausência de erros visíveis.'),X('Name relevant quality attributes and define how evidence will be gathered.','Nombra atributos de calidad pertinentes y define cómo reunir evidencia.','Nomeie atributos de qualidade relevantes e defina como reunir evidências.')],
 [
  {title:X('Choose quality evidence','Elige evidencia de calidad','Escolha evidências de qualidade'),prompt:X('A transit app must remain usable with screen readers. What quality attribute and evidence fit?','Una app de transporte debe funcionar con lectores de pantalla. ¿Qué atributo y evidencia corresponden?','Um aplicativo de transporte precisa funcionar com leitores de tela. Que atributo e evidência se aplicam?'),hint:X('Consider access needs and observable checks.','Considera necesidades de acceso y comprobaciones observables.','Considere necessidades de acesso e verificações observáveis.'),solution:X('Accessibility is the attribute; test representative flows with assistive technology and users who rely on it.','La accesibilidad es el atributo; se prueban flujos representativos con tecnología de asistencia y usuarios que la utilizan.','Acessibilidade é o atributo; teste fluxos representativos com tecnologia assistiva e pessoas que a utilizam.'),level:2},
  {title:X('Plan for evolution','Planifica la evolución','Planeje a evolução'),prompt:X('List two changes that might require a released program to evolve.','Enumera dos cambios que podrían requerir la evolución de un programa publicado.','Liste duas mudanças que podem exigir a evolução de um programa lançado.'),hint:X('Consider users, laws, and technology.','Considera usuarios, normas y tecnología.','Considere usuários, regras e tecnologia.'),solution:X('Examples include new user needs, security fixes, updated devices or operating systems, and policy changes.','Ejemplos: nuevas necesidades, correcciones de seguridad, dispositivos o sistemas operativos actualizados y cambios de políticas.','Exemplos: novas necessidades, correções de segurança, dispositivos ou sistemas operacionais atualizados e mudanças de regras.'),level:1}
 ])
);
lessons.push(
 mkLesson('hist2-l5',X('Professional responsibility and ethics','Responsabilidad profesional y ética','Responsabilidade profissional e ética'),[
  X('Software decisions affect people beyond the development team. A system may influence privacy, safety, access to services, employment, or public information. Professional responsibility means considering foreseeable effects, communicating limitations honestly, protecting confidential information, and escalating serious risks.','Las decisiones de software afectan a personas fuera del equipo. Un sistema puede influir en privacidad, seguridad física, acceso a servicios, empleo o información pública. La responsabilidad profesional implica considerar efectos previsibles, comunicar limitaciones con honestidad, proteger información confidencial y escalar riesgos graves.','Decisões de software afetam pessoas além da equipe. Um sistema pode influenciar privacidade, segurança, acesso a serviços, emprego ou informação pública. Responsabilidade profissional significa considerar efeitos previsíveis, comunicar limitações com honestidade, proteger informações confidenciais e escalar riscos graves.'),
  X('Codes of ethics offer shared guidance, but they do not replace judgment or local law. When a deadline conflicts with safety or privacy, a professional should document evidence, explain the risk, involve the appropriate decision-makers, and seek a safer path. A responsible choice may require delaying release or narrowing scope.','Los códigos de ética ofrecen una guía común, pero no sustituyen el criterio profesional ni las leyes aplicables. Si un plazo entra en conflicto con la seguridad o privacidad, se debe documentar evidencia, explicar el riesgo, involucrar a quienes deciden y buscar una alternativa más segura. Puede ser necesario retrasar la publicación o reducir el alcance.','Códigos de ética oferecem orientação compartilhada, mas não substituem julgamento profissional nem leis locais. Se um prazo conflitar com segurança ou privacidade, é preciso documentar evidências, explicar o risco, envolver responsáveis pela decisão e buscar um caminho mais seguro. Pode ser necessário adiar o lançamento ou reduzir o escopo.')],
 X('An engineer’s signature on a safety inspection means considering the people who will rely on the structure, not just the construction schedule.','La firma de una persona ingeniera en una inspección de seguridad implica pensar en quienes dependerán de la estructura, no solo en el calendario.','A assinatura de uma pessoa engenheira em uma inspeção de segurança considera quem dependerá da estrutura, não apenas o cronograma.'),
 [X('Ethical practice includes candor about risks and limitations.','La práctica ética incluye sinceridad sobre riesgos y limitaciones.','A prática ética inclui transparência sobre riscos e limitações.'),X('Public impact belongs in software decisions.','El impacto público forma parte de las decisiones de software.','O impacto público faz parte das decisões de software.')],
 [X('A team discovers a serious privacy flaw shortly before release. What is the responsible first step?','Un equipo detecta una falla grave de privacidad antes del lanzamiento. ¿Cuál es un primer paso responsable?','Uma equipe encontra uma falha grave de privacidade pouco antes do lançamento. Qual é um primeiro passo responsável?'),X('Document evidence and promptly raise the risk with responsible decision-makers.','Documentar evidencia y comunicar el riesgo a quienes deciden.','Documentar evidências e comunicar o risco a quem decide.'),X('Hide the issue to protect the schedule.','Ocultar el problema para proteger el plazo.','Ocultar o problema para proteger o prazo.'),X('Delete the test result.','Eliminar el resultado de la prueba.','Excluir o resultado do teste.'),X('Assume users will never notice.','Suponer que nadie lo notará.','Supor que ninguém perceberá.'),'0',X('Honest escalation allows the organization to assess and reduce foreseeable harm.','La comunicación honesta permite evaluar y reducir daños previsibles.','A comunicação honesta permite avaliar e reduzir danos previsíveis.'),X('Assuming a code of ethics gives one automatic answer to every conflict.','Suponer que un código ético da una respuesta automática a todo conflicto.','Supor que um código de ética fornece uma resposta automática a todo conflito.'),X('Use the code as guidance, then apply evidence, context, and professional judgment.','Usa el código como guía y aplica evidencia, contexto y criterio profesional.','Use o código como orientação e aplique evidências, contexto e julgamento profissional.')],
 [
  {title:X('Analyze an ethical tension','Analiza una tensión ética','Analise um conflito ético'),prompt:X('A manager asks the team to collect extra personal data “just in case.” Identify a concern and a responsible response.','Una persona gerente pide recopilar datos personales extra “por si acaso”. Identifica un riesgo y una respuesta responsable.','Uma pessoa gerente pede a coleta de dados pessoais extras “por precaução”. Identifique um risco e uma resposta responsável.'),hint:X('Ask whether the data is necessary, protected, and explained.','Pregunta si los datos son necesarios, protegidos y explicados.','Pergunte se os dados são necessários, protegidos e explicados.'),solution:X('Minimize unnecessary collection, clarify purpose and retention, assess privacy risk, and explain options to decision-makers.','Minimizar la recopilación, aclarar propósito y retención, evaluar riesgos de privacidad y explicar opciones a quienes deciden.','Minimize a coleta desnecessária, esclareça finalidade e retenção, avalie riscos de privacidade e explique opções aos responsáveis.'),level:2},
  {title:X('Write an escalation note','Redacta una nota de escalamiento','Escreva uma nota de escalonamento'),prompt:X('Draft the elements of a short note reporting a safety risk.','Esboza los elementos de una nota breve que informe un riesgo de seguridad.','Esboce os elementos de uma nota curta que relate um risco de segurança.'),hint:X('Include evidence, impact, uncertainty, and a next action.','Incluye evidencia, impacto, incertidumbre y una acción siguiente.','Inclua evidências, impacto, incerteza e uma próxima ação.'),solution:X('State the observed evidence, who may be affected, how certain the assessment is, what mitigation is available, and who should decide next.','Indica evidencia, personas afectadas, certeza de la evaluación, mitigación posible y quién debe decidir el siguiente paso.','Informe evidências, pessoas afetadas, grau de certeza, mitigação disponível e quem deve decidir o próximo passo.'),level:3}
 ])
);

